static REGISTRY: OnceLock<Mutex<HashMap<String, Arc<Conn>>>> = OnceLock::new();

fn conn_for(tenant: &str) -> Arc<Conn> {
    let map = REGISTRY.get_or_init(|| Mutex::new(HashMap::new()));
    let mut guard = map.lock().expect("registry poisoned");
    guard
        .entry(tenant.to_owned())
        .or_insert_with(|| Arc::new(Conn::open(tenant)))
        .clone()
}

