fn slot(tenant: &str) -> Arc<OnceLock<Arc<Conn>>> {
    let map = REGISTRY.get_or_init(|| Mutex::new(HashMap::new()));
    Arc::clone(
        map.lock().unwrap()
            .entry(tenant.to_owned())
            .or_insert_with(|| Arc::new(OnceLock::new())),
    )
